// План specs/admin-access.md, 5.3 и 5.4 (кейс AA-11). Пользователь «בדיקה», EN и HE. Только чтение. @prod-safe
// Ловит мелькание «AdminPanel» в крошках/заголовке/тексте страницы на пути /adminpanel → /dashboard (#26087e6e).
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL } from './access-helpers';
import { CRUMB, USER_STATE, expectCrumb, expectNoScreenNameFlash, installCrumbRecorder } from './crumb-helpers';

test.use({ storageState: USER_STATE });

test.describe('Крошки без названия закрытого экрана — обычный пользователь (#26087e6e)', () => {
  for (const lang of ['en', 'he'] as const) {
    test(`Non-admin redirected from /adminpanel never sees the closed screen name in breadcrumbs, title or page (${lang.toUpperCase()}) #26087e6e @desktop @prod-safe`, async ({ page }) => {
      await setLanguage(page, lang);
      await installCrumbRecorder(page);

      await page.goto('/adminpanel');
      await expect(page).toHaveURL(DASHBOARD_URL);
      await expectCrumb(page, CRUMB[lang].home);
      await expectNoScreenNameFlash(page, CRUMB[lang].home);
    });
  }
});
